iption":"What a receipt says of the event a registration belongs to: enough for the registrant\'s agent to show it as it was when the community answered (VTI-EVT-092).","type":"object","additionalProperties":false,"required":["eventId","title","when","status","sequence"],"properties":{"eventId":{"\$ref":"#/\$defs/EventId"},"title":{"\$ref":"#/\$defs/EventTitle"},"when":{"\$ref":"#/\$defs/When"},"status":{"\$ref":"#/\$defs/EventLifecycle"},"sequence":{"type":"integer","minimum":0}}},"EventLifecycle":{"title":"EventLifecycle","description":"`draft`: seen only by its hosts, changes freely, takes no registrations. `published`: seen by its audience, takes registrations; its roster setting is fixed. `cancelled`: will not happen; kept so registrants and their agents see it was cancelled, and takes no registrations. Whether a published event has ended is read from its time, never stored (VTI-EVT-004).","type":"string","enum":["draft","published","cancelled"]},"When":{"title":"When","description":"When the event happens, in JSCalendar\'s terms. `start` is local time in `timeZone`; `duration` is how long it lasts. With `showWithoutTime` true it is an all-day event: `start`\'s time MUST be `T00:00:00` and `duration` whole days (VTI-EVT-005).","type":"object","additionalProperties":false,"required":["start","timeZone","duration"],"properties":{"start":{"\$ref":"#/\$defs/LocalDateTime"},"timeZone":{"\$ref":"#/\$defs/TimeZoneId"},"duration":{"\$ref":"#/\$defs/JSCalendarDuration"},"showWithoutTime":{"type":"boolean","description":"An all-day event. Absent means false."}}},"JSCalendarDuration":{"title":"JSCalendarDuration","description":"A non-negative duration in the subset of ISO 8601 JSCalendar uses: `P` then weeks or days, then `T` with hours, minutes and seconds, such as `PT1H30M`, `P1D` or `P2W`. No months or years. Used only for `When.duration`, which carries JSCalendar\'s own member and encoding verbatim; this family\'s own offsets are integers naming their unit (`ReminderMinutes`).","type":"string","minLength":3,"maxLength":32,"pattern":"^P(?!\$)([0-9]+W)?([0-9]+D)?(T(?=[0-9])([0-9]+H)?([0-9]+M)?([0-9]+S)?)?\$"},"TimeZoneId":{"title":"TimeZoneId","description":"An IANA time zone name, such as `Europe/London`, or `Etc/UTC`. A responder MUST refuse a name its time zone database does not know.","type":"string","minLength":1,"maxLength":64,"pattern":"^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+){0,2}\$"},"LocalDateTime":{"title":"LocalDateTime","description":"A local date and time with no offset, `YYYY-MM-DDTHH:MM:SS`, as JSCalendar\'s LocalDateTime. Read in the event\'s `timeZone`.","type":"string","pattern":"^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]\$"},"EventTitle":{"title":"EventTitle","type":"string","minLength":1,"maxLength":200,"description":"A short name. Plain text; a reader MUST NOT treat it as instructions."},"EventId":{"title":"EventId","description":"Opaque identifier of an event: `evt_` followed by 16 to 64 base64url characters. Random, community-scoped, never reused (VTI-EVT-001).","type":"string","pattern":"^evt_[A-Za-z0-9_-]{16,64}\$"}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
